import {FLEET_CONNECTIONS,FLEET_QUALIFICATION,fleetRecordOf,fleetCompleteness,summarizeFleet} from './fleet-registry.js';

const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const techLabel=tech=>({resin:'RÉSINE UV',fdm:'FDM',unknown:'PROCÉDÉ À PRÉCISER'}[tech]||'À PRÉCISER');
const number=value=>Number(value).toLocaleString('fr-FR',{maximumFractionDigits:3});

export function renderFleetRegistry({machines,esc=escapeHTML,icon=()=>''}){
  const summary=summarizeFleet(machines);
  return `<section class="fleet-registry" aria-labelledby="fleet-title">
    <header class="fleet-heading"><div><p class="fleet-kicker"><i></i> BOJ.ART / LE PARC</p><h2 id="fleet-title">CONNAÎTRE<br><em>CHAQUE MACHINE.</em></h2><p>Un emplacement. Une fiche. Les bonnes informations pour préparer la suite.</p></div><div class="fleet-heading-mark" aria-hidden="true"><img src="./assets/logo.webp" alt=""><span>${String(summary.slots).padStart(2,'0')} <small>EMPLACEMENTS</small></span></div></header>
    <div class="fleet-summary" aria-label="Complétude du référentiel"><div><strong>${String(summary.declared).padStart(2,'0')}</strong><span>machines renseignées</span></div><div><strong>${String(summary.complete).padStart(2,'0')}</strong><span>fiches complètes</span></div><div><strong>${String(summary.examples).padStart(2,'0')}</strong><span>exemples à remplacer</span></div><span class="fleet-summary-note">Le raccordement des machines<br>reste à réaliser.</span></div>
    <div class="fleet-slots">${summary.records.map(({id,record:r,completeness:c},index)=>`<button type="button" class="fleet-slot ${c.status}" data-fleet-machine="${esc(id)}" style="--fleet-order:${index}" aria-label="Ouvrir ${esc(id)} — ${esc(r.model||'emplacement à renseigner')} — ${esc(c.label)}"><div class="fleet-slot-top"><strong>${esc(id)}</strong><span class="fleet-state ${c.status}">${esc(c.label)}</span></div><div class="fleet-slot-viz" aria-hidden="true"><i class="fleet-slot-halo"></i>${icon('printer')}<span>${String(index+1).padStart(2,'0')}</span></div><div class="fleet-slot-title"><small>${r.origin==='declared'?esc(r.manufacturer||'FABRICANT À PRÉCISER'):'EMPLACEMENT DE DÉMONSTRATION'}</small><h3>${r.origin==='declared'?esc(r.model||'Modèle à préciser'):'À renseigner'}</h3><p>${r.origin==='declared'?techLabel(r.technology):'PROCÉDÉ RÉEL À PRÉCISER'}</p></div><div class="fleet-slot-volume">${r.usableVolumeMm?`<strong>${r.usableVolumeMm.map(number).join(' × ')} <small>mm</small></strong><span>Volume déclaré</span>`:'<span>Volume utile à renseigner</span>'}</div><div class="fleet-slot-progress"><span>FICHE <b>${c.completed} / ${c.total}</b></span><i><b style="--fleet-completion:${c.percent}%"></b></i></div><span class="fleet-slot-open">${r.origin==='declared'?'Compléter la fiche':'Renseigner la machine'} ${icon('arrowUp')}</span></button>`).join('')}</div>
    <div class="fleet-lower"><div><span class="fleet-kicker">LE PROCHAIN JALON</span><h3>Un premier assemblage,<br>sur deux procédés.</h3><p>Renseigner une FDM et une résine, retrouver leurs profils, puis documenter leur premier essai.</p></div><ol class="fleet-readiness"><li><span>01</span><p><strong>Identifier</strong><small>Machine, volume et firmware</small></p></li><li><span>02</span><p><strong>Préparer</strong><small>Matière, slicer et profils</small></p></li><li><span>03</span><p><strong>Éprouver</strong><small>Fichier, fabrication et assemblage</small></p></li></ol></div>
    <footer class="fleet-footer"><p>« Fiche complète » décrit les champs renseignés. La connexion et la qualification nécessitent leur propre vérification.</p><button type="button" class="button" data-action="export-fleet">${icon('save')} Exporter le référentiel</button></footer>
  </section>`;
}

export function renderFleetForm({machine,esc=escapeHTML,icon=()=>''}){
  const r=fleetRecordOf(machine),c=fleetCompleteness(r);
  const input=(label,name,value='',attributes='')=>`<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}" ${attributes}></label>`;
  const select=(label,name,value,options)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>`<option value="${o.id}" ${o.id===value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label>`;
  const section=(n,title,description,body,open=false)=>`<details class="fleet-form-section" ${open?'open':''}><summary><span>${n}</span><div><strong>${title}</strong><small>${description}</small></div><i aria-hidden="true">+</i></summary><div class="fleet-section-body">${body}</div></details>`;
  const updated=r.updatedAt!==null?new Date(r.updatedAt).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Paris'}):'';
  return `<section class="fleet-editor" aria-labelledby="fleet-editor-title"><header class="fleet-editor-head"><button type="button" class="fleet-back" data-action="fleet">${icon('arrow')} Le parc</button><span class="fleet-state ${c.status}">${esc(c.label)}</span><div><p class="fleet-kicker">BOJ.ART / FICHE MACHINE</p><h2 id="fleet-editor-title"><span>${esc(machine.id)}</span> ${esc(r.model||'À RENSEIGNER')}</h2><p>Les informations réelles de l’atelier restent séparées du scénario de démonstration.</p></div></header>
    <div class="fleet-form-completion" aria-label="${c.completed} groupes de renseignements complets sur ${c.total}">${c.groups.map(g=>`<span class="${g.complete?'complete':''}" title="${esc(g.complete?g.label+' renseigné':g.missing.join(', '))}"><i>${g.complete?'✓':'·'}</i>${esc(g.label)}</span>`).join('')}</div>
    <form id="fleet-form" data-id="${esc(machine.id)}" data-revision="${r.revision}" autocomplete="off">
      <fieldset class="fleet-origin"><legend>Cette fiche décrit…</legend><label><input type="radio" name="origin" value="example" ${r.origin==='example'?'checked':''}><span><strong>Un exemple</strong><small>Emplacement de démonstration</small></span></label><label><input type="radio" name="origin" value="declared" ${r.origin==='declared'?'checked':''}><span><strong>Une machine de l’atelier</strong><small>Informations que vous renseignez</small></span></label></fieldset>
      ${section('01','Identifier la machine','Fabricant, modèle et emplacement.',`<div class="form-grid">${input('Fabricant','manufacturer',r.manufacturer,'type="text" maxlength="120" placeholder="À renseigner"')}${input('Modèle exact','model',r.model,'type="text" maxlength="160" placeholder="À renseigner"')}${input('Numéro de série ou identifiant atelier','serial',r.serial,'type="text" maxlength="160"')}${input('Position dans l’atelier','location',r.location,'type="text" maxlength="160"')}${input('Firmware et version','firmware',r.firmware,'type="text" maxlength="160"')}${select('Procédé','tech',r.technology,[{id:'unknown',label:'À préciser'},{id:'fdm',label:'FDM'},{id:'resin',label:'Résine UV'}])}</div>`,true)}
      ${section('02','Mesurer le volume utile','Dimensions de fabrication, en millimètres.',`<div class="fleet-volume-fields">${['X','Y','Z'].map((axis,i)=>input(axis+' / mm','volume'+axis,r.usableVolumeMm?.[i]??'','type="text" inputmode="decimal" maxlength="60" placeholder="—"')).join('')}</div><p class="fleet-field-note">Conserver les axes X, Y et Z de la machine. Les supports et espacements sont à prévoir lors de la préparation.</p>${input('Source des dimensions ou mesure','volumeSource',r.volumeSource,'type="text" maxlength="500" placeholder="Référence du manuel, profil ou mesure…"')}`)}
      ${section('03','Retrouver les profils','Slicer, matière et profils de préparation.',`<div class="form-grid">${input('Slicer','slicerName',r.slicer.name,'type="text" maxlength="120"')}${input('Version du slicer','slicerVersion',r.slicer.version,'type="text" maxlength="100"')}${input('Nom ou référence du profil machine','machineProfile',r.slicer.machineProfile,'type="text" maxlength="240"')}${input('Nom ou référence du profil matière','materialProfile',r.slicer.materialProfile,'type="text" maxlength="240"')}</div>${input('Matière prévue et référence','material',r.material,'type="text" maxlength="240"')}<p class="fleet-field-note">Le nom d’un profil permet de le retrouver. Le fichier de profil devra être fourni et qualifié avec le moteur de slicing.</p>`)}
      ${section('04','Préparer le transfert','Format de sortie et interface disponible.',`${input('Extensions des fichiers acceptés','formats',r.fileFormats.join(', '),'type="text" maxlength="400" placeholder="Extensions séparées par des virgules"')}<div class="form-grid">${select('Interface de la machine','connectionKind',r.connection.kind,FLEET_CONNECTIONS)}${input('Adresse de l’interface réseau','endpoint',r.connection.endpoint,'type="url" maxlength="500" placeholder="http://adresse:port"')}</div><p class="fleet-field-note">Renseigner l’adresse prépare le raccordement. Aucun appel réseau n’est effectué depuis cette fiche. Les clés et mots de passe restent hors du référentiel.</p>`)}
      ${section('05','Documenter le premier essai','Résultat déclaré, rattaché à cette configuration.',`<div class="form-grid">${select('État du dossier d’essai','qualificationStatus',r.qualification.status,FLEET_QUALIFICATION)}${input('Date de l’essai','testedOn',r.qualification.testedOn,'type="date"')}${input('Responsable de l’essai','operator',r.qualification.operator,'type="text" maxlength="160"')}</div><label class="field"><span>Référence du rapport et résultat observé</span><textarea name="report" rows="4" maxlength="2000" placeholder="Pièce testée, fichier, résultat, mesures, défauts…">${esc(r.qualification.report)}</textarea></label><p class="fleet-field-note">Un essai documenté nécessite date, responsable et résultat. Un changement de configuration remet l’essai à reprendre lorsque la même preuve est conservée.</p>`)}
      <label class="field fleet-notes"><span>Notes pour la préparation</span><textarea name="notes" rows="3" maxlength="4000" placeholder="Points à vérifier, accessoires, lavage, polymérisation…">${esc(r.notes)}</textarea></label>
      <div id="form-error" class="inline-error" role="alert"></div><div class="fleet-save-row"><div><strong>Fiche ${esc(machine.id)}${r.revision?' · révision '+r.revision:''}</strong><small>${updated?'Dernier enregistrement : '+esc(updated):'Aucune machine réelle encore renseignée à cet emplacement.'}</small></div><button class="button button-red" type="submit">${icon('save')} Enregistrer la fiche</button></div><p class="fleet-field-note fleet-save-note">L’enregistrement conserve les travaux et dimensions du scénario de simulation.</p>
    </form>
  </section>`;
}
